using pluss::ScalarType;
using pluss::Series;
using pluss::make_series;
namespace tape = pluss::codem::series_tape;

enum class R { TRACKED, NO_NODE, NONDIFF_DTYPE, SKIPPED_BY_DESIGN, THREW };

struct Row { std::string key; R r; };
std::vector<Row>& rows() { static std::vector<Row> v; return v; }

const char* kManifestPath = "series_backward_manifest.txt";
std::ofstream& sink() {
  static std::ofstream s(kManifestPath, std::ios::trunc);
  return s;
}

Series probe_input() {
  return make_series(std::vector<double>{0.3, -0.7, 1.1, 0.4, -0.2, 0.9}, {2, 3})
      .to(ScalarType::Float64);
}

// Rows already triaged as an accepted "no node" outcome -- see
// KNOWN_NO_NODE in the generator for the reason each was added.
const std::set<std::string>& known_no_node() {
  static const std::set<std::string> s{
      "airy()",
      "bernoulli(double)",
      "besseli()",
      "besseli(double)",
      "besselj()",
      "besselj(double)",
      "besselk()",
      "besselk(double)",
      "bessely()",
      "bessely(double)",
      "fix()",
      "floor_divide(const Series&)",
      "floor_divide(double)",
      "heaviside(const Series&)",
      "heaviside(double)",
      "igamma(double)",
      "igammac(double)",
      "imag()",
      "new_empty(pluss::msharp::RangeView::Int)",
      "new_empty_strided(pluss::msharp::RangeView::Int)",
      "new_empty_strided(pluss::msharp::RangeView::Int, pluss::msharp::RangeView::Int)",
      "new_full(pluss::msharp::RangeView::Int, double)",
      "new_ones(pluss::msharp::RangeView::Int)",
      "new_zeros(pluss::msharp::RangeView::Int)",
      "nextafter(const Series&)",
      "q_per_channel_scales()",
      "q_scale()",
      "resize_(pluss::msharp::RangeView::Int)",
      "sgn()",
      "union1d(const Series&)",
      "unionize(RangeView::Of<Series>)",
      "intersect1d(const Series&)",
      "intersection(RangeView::Of<Series>)",
      "setdiff1d(const Series&)",
      "setxor1d(const Series&)",
      "sign()",
      "unique()",
      "zeta(double)",
  };
  return s;
}

template <class F>
void probe(const std::string& name, const std::string& sig, F&& f) {
  const std::string key = name + sig;
  R r;
  std::string detail;
  try {
    Series y = f();
    const bool has_node = tape::source_info(y).has_value() || tape::tracks_slope(y);
    const bool is_diff_dtype = y.is_floating_point() || y.is_complex();
    if (!is_diff_dtype) {
      r = R::NONDIFF_DTYPE;
    } else if (has_node) {
      r = R::TRACKED;
    } else if (known_no_node().count(key)) {
      r = R::SKIPPED_BY_DESIGN;
    } else {
      r = R::NO_NODE;
    }
  } catch (const std::exception& e) {
    r = R::THREW;
    detail = e.what();
  } catch (...) {
    r = R::THREW; detail = "non-std exception";
  }
  rows().push_back({key, r});
  static const char* names[] = 
      {"TRACKED", "NO_NODE", "NONDIFF_DTYPE", "SKIPPED_BY_DESIGN", "THREW"};
  sink() << names[static_cast<int>(r)] << "\t" << key;
  if (!detail.empty()) sink() << "\t" << detail.substr(0, 160);
  sink() << "\n";
  sink().flush();
}

